// The entry files of a draft version, generated from its layout.

import { pascalCase } from './names.ts';

const BANNER =
  '// Generated by kitvas from md/layout.md. Do not edit: change the layout and run "kitvas layout".';

export function entryTsx(sections: { id: string }[]): string {
  const names = sections.map((section) => pascalCase(section.id));
  return [
    BANNER,
    ...names.map((name) => `import { ${name} } from './sections/${name}.tsx';`),
    '',
    'export type DraftProps = { state: string };',
    '',
    'export function Draft({ state }: DraftProps) {',
    '  return (',
    '    <>',
    ...names.map((name) => `      <${name} state={state} />`),
    '    </>',
    '  );',
    '}',
    '',
  ].join('\n');
}

export function entryScss(sections: { id: string }[]): string {
  return [BANNER, ...sections.map((section) => `@use 'sections/${section.id}';`), ''].join('\n');
}
